insert into public.comment_series_profiles (profile, route_label, platform, route, comment_services,
    series_text, steps, push, replies_text)
values
  ('fb_page', 'Facebook Pages, green', 'facebook', 'green', array['fb-post-comments-fetcher']::text[], '+1 h, +6 h, +24 h, +3 d, +7 d, then weekly to day 30', array['+1h', '+6h', '+24h', '+3d', '+7d', '+14d', '+21d', '+28d']::text[], false, 'in the stream (`filter=stream`); no ids, dedup by hash'),
  ('fb_group', 'Facebook groups, amber', 'facebook', 'amber', array['fb-group-comments-fetcher']::text[], '+1 h, +6 h, +24 h, +3 d', array['+1h', '+6h', '+24h', '+3d']::text[], false, 'one `replies` job per post, by comment id when the vendor exposes it (ADR-0060)'),
  ('ig_own', 'Instagram client media, green', 'instagram', 'green', array['ig-own-comments-fetcher']::text[], '+1 h, +6 h, +24 h, +3 d, +7 d, then weekly to day 30', array['+1h', '+6h', '+24h', '+3d', '+7d', '+14d', '+21d', '+28d']::text[], false, 'field expansion on the same call; no `replies` job (ADR-0060)'),
  ('ig_other', 'Instagram other media, amber', 'instagram', 'amber', array['ig-comments-fetcher']::text[], '+6 h, +24 h, +3 d', array['+6h', '+24h', '+3d']::text[], false, 'none (about 15 visible comments)'),
  ('tt', 'TikTok, amber', 'tiktok', 'amber', array['tt-video-comments-fetcher']::text[], '+1 h, +6 h, +24 h, +3 d, +7 d', array['+1h', '+6h', '+24h', '+3d', '+7d']::text[], false, 'one `replies` job per post for comments with more than 10 replies (ADR-0060)'),
  ('x', 'X, green', 'x', 'green', array['x-replies-fetcher', 'x-full-archive-search']::text[], '+1 h, +6 h, +24 h, +3 d, then +7 d and weekly to day 30 (ADR-0059)', array['+1h', '+6h', '+24h', '+3d', '+7d', '+14d', '+21d', '+28d']::text[], false, 'replies and quotes by `conversation_id:`; after +3 d, `replies` jobs on `jobs.x-full-archive-search` with `window_start`'),
  ('yt', 'YouTube, green', 'youtube', 'green', array['yt-comments-fetcher', 'yt-replies-fetcher']::text[], '+6 h, +24 h, +3 d, +7 d, +30 d', array['+6h', '+24h', '+3d', '+7d', '+30d']::text[], false, 'one `replies` job per post to yt-replies-fetcher for threads with more than 5 replies (ADR-0060)'),
  ('li_own', 'LinkedIn client posts, green', 'linkedin', 'green', array['li-own-comments-fetcher']::text[], '+6 h, +24 h, +3 d', array['+6h', '+24h', '+3d']::text[], false, 'in the same call; member data purged after 48 h'),
  ('li_other', 'LinkedIn other posts, amber', 'linkedin', 'amber', array['li-post-comments-fetcher']::text[], '+24 h, +3 d', array['+24h', '+3d']::text[], false, 'none'),
  ('tg_own', 'Telegram own channels, green', 'telegram', 'green', array['tg-discussion-receiver']::text[], 'push (live); its own daily `reconciliation` check per group (ADR-0012)', array[]::text[], true, 'live'),
  ('news', 'News (Disqus sites), green', 'news', 'green', array['news-comments-fetcher']::text[], '+6 h, +24 h, +3 d', array['+6h', '+24h', '+3d']::text[], false, 'threaded in the same call')
on conflict do nothing;
